-- 미시경제 레슨 2: 809 손익분기점, 794 가격차별, 788 게임이론, 521 죄수의 딜레마, 787 독점적 경쟁, 832 경제적 지대, 551 지니계수, 627 파레토최적, 406 외부효과, 798 코즈의 정리, 49 공공재, 799 공유지의 비극, 792 역선택, 181 도덕적 해이
-- 근거: 테셋05~36 블로그 글(탄력성·잉여·조세·한계·생산가능곡선·무차별곡선·생산·비용·시장구조·지대·분배·후생·시장실패·정보 비대칭).
-- 카드(text/table/flow)와 퀴즈 2개(그중 lessonCheck 1개)를 기존 visuals 앞에 붙인다. 첫 카드 제목이 이미 있으면 건너뜀(다시 실행해도 중복 없음).

-- 손익분기점 (809)
UPDATE public.words SET visuals = '[
  {"type": "text", "title": "손익분기점 쉽게 설명", "body": "총수입과 총비용이 같아 이익도 손실도 없는 본전 판매량이에요.\n빵을 3,000원에 팔고 재료비가 1,000원이면 하나 팔 때 2,000원이 남아요. 이걸로 월 임대료 100만 원을 메우려면 500개를 팔아야 해요."},
  {"type": "table", "title": "본전까지 팔아야 하는 양", "columns": ["판매량", "총수입", "총비용", "이윤"], "rows": [["200개", "60만 원", "120만 원", "-60만 원"], ["500개", "150만 원", "150만 원", "0"], ["800개", "240만 원", "180만 원", "+60만 원"]], "caption": "손익분기점 판매량 = 고정비용 ÷ (가격 - 개당 가변비용)"},
  {"type": "text", "title": "손익분기점과 조업중단점", "body": "완전경쟁 기업의 그래프에서는 가격이 평균비용의 가장 낮은 점과 같을 때가 손익분기점이에요.\n가격이 그보다 낮아도 평균가변비용보다 높으면 단기에는 계속 만드는 게 손실이 적어요. 평균가변비용 최저점 아래로 내려가면 생산을 멈추는데, 이 점이 조업중단점이에요."},
  {"type": "quiz", "q": "월 고정비용이 200만 원인 가게가 컵 하나를 5,000원에 팔고, 컵 하나의 재료비는 1,000원이에요. 손익분기점 판매량은?", "options": ["500개", "400개", "2,000개", "40개"], "answer": 0, "explanation": "하나 팔 때 5,000원 - 1,000원 = 4,000원이 남아요. 200만 원 ÷ 4,000원 = 500개를 팔아야 본전이에요.", "lessonCheck": true},
  {"type": "quiz", "q": "완전경쟁 기업에서 가격이 평균비용 최저점보다 낮지만 평균가변비용 최저점보다는 높아요. 단기에 어떻게 하는 게 유리할까요?", "options": ["손실이 나도 생산을 계속해요", "바로 생산을 멈춰요", "가격을 시장보다 올려 받아요", "생산량을 무한히 늘려요"], "answer": 0, "explanation": "가변비용을 건지고 남는 돈으로 고정비 일부를 메울 수 있어요. 문을 닫으면 고정비를 전부 잃으니 계속 생산하는 게 손실이 적어요."}
]'::jsonb || COALESCE(visuals,'[]'::jsonb)
WHERE id = 809 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "손익분기점 쉽게 설명"}]'::jsonb;

-- 가격차별 (794)
UPDATE public.words SET visuals = '[
  {"type": "text", "title": "가격차별 쉽게 설명", "body": "같은 물건을 사람이나 사는 양에 따라 다른 값에 파는 거예요. 조조할인, 학생할인, 대용량 할인이 모두 가격차별이에요.\n가능하려면 독점력이 있고, 손님을 나눌 수 있고, 싸게 산 사람이 되팔 수 없어야 해요."},
  {"type": "table", "title": "가격차별 1·2·3급", "columns": ["구분", "방식", "특징"], "rows": [["1급", "손님마다 최대 지불 의사만큼 받음", "소비자잉여 0, 생산량은 완전경쟁과 같음"], ["2급", "많이 살수록 단위당 싸게", "묶음·대용량 할인"], ["3급", "집단마다 다른 가격", "가격에 민감한(탄력적인) 집단이 더 쌈"]], "caption": "1급은 사중손실이 없어 효율은 높지만, 잉여가 모두 기업에게 가요."},
  {"type": "quiz", "q": "영화관이 일반 관객보다 학생에게 더 싸게 표를 팔아요. 그 이유로 가장 알맞은 것은?", "options": ["학생 수요가 가격에 더 민감(탄력적)해서", "학생에게 상영 비용이 더 적게 들어서", "학생이 표를 되팔 수 있어서", "일반 관객 수요가 더 탄력적이어서"], "answer": 0, "explanation": "3급 가격차별에서는 비싸면 안 사는 탄력적인 집단에 싸게, 비싸도 사는 비탄력적인 집단에 비싸게 받아요.", "lessonCheck": true},
  {"type": "quiz", "q": "가격차별이 아닌 것은?", "options": ["품질과 비용이 다른 두 상품에 다른 값을 받는 것", "같은 영화를 아침에 싸게 파는 조조할인", "같은 상품을 많이 사면 단위당 싸게 주는 것", "같은 상품을 나라마다 다른 값에 파는 것"], "answer": 0, "explanation": "가격차별은 같은 물건을 다른 값에 파는 거예요. 품질이나 비용이 다른 물건에 다른 값을 받는 건 가격차별이 아니에요."}
]'::jsonb || COALESCE(visuals,'[]'::jsonb)
WHERE id = 794 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "가격차별 쉽게 설명"}]'::jsonb;

-- 게임이론 (788)
UPDATE public.words SET visuals = '[
  {"type": "text", "title": "게임이론 쉽게 설명", "body": "내 결과가 상대의 선택에 따라 달라질 때, 서로의 반응을 따져 전략을 고르는 상황을 분석하는 도구예요.\n몇 개 기업이 서로 눈치를 보는 과점시장을 설명할 때 많이 써요.\n선택에 따라 각자 얻는 결과를 정리한 표를 보수표라고 해요."},
  {"type": "table", "title": "우월전략 균형 vs 내쉬 균형", "columns": ["구분", "우월전략 균형", "내쉬 균형"], "rows": [["뜻", "모두가 상대와 상관없이 늘 나은 전략을 고른 상태", "상대 전략이 주어졌을 때 서로 최선을 고른 상태"], ["개수", "있으면 하나", "없을 수도, 하나일 수도, 여러 개일 수도"], ["관계", "항상 내쉬 균형이에요", "우월전략 균형이 아닐 수 있어요"]]},
  {"type": "text", "title": "보수표에서 균형 찾기", "body": "상대의 전략마다 나에게 가장 좋은 칸에 밑줄을 그어요.\n상대도 똑같이 밑줄을 긋고, 두 사람 모두 밑줄 친 칸이 내쉬 균형이에요. 여기서는 누구도 혼자 전략을 바꿀 이유가 없어요."},
  {"type": "quiz", "q": "A 기업은 B 기업이 광고를 하든 안 하든, 자기가 광고하는 쪽의 이윤이 더 커요. A에게 광고하기는 어떤 전략일까요?", "options": ["우월전략", "열위전략", "협조 전략", "무임승차 전략"], "answer": 0, "explanation": "상대가 무엇을 하든 나에게 늘 더 나은 전략을 우월전략이라고 해요.", "lessonCheck": true},
  {"type": "quiz", "q": "내쉬 균형에 대한 설명으로 옳은 것은?", "options": ["한 게임에 내쉬 균형이 여러 개 있을 수 있어요", "내쉬 균형은 언제나 모두에게 가장 좋은 결과예요", "내쉬 균형은 언제나 우월전략 균형이에요", "내쉬 균형에서는 혼자 전략을 바꾸면 이득이에요"], "answer": 0, "explanation": "서로 최선 대응인 칸이 여러 개면 내쉬 균형도 여러 개예요. 죄수의 딜레마처럼 균형이 모두에게 더 나쁜 결과일 수도 있어요."}
]'::jsonb || COALESCE(visuals,'[]'::jsonb)
WHERE id = 788 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "게임이론 쉽게 설명"}]'::jsonb;

-- 죄수의 딜레마 (521)
UPDATE public.words SET visuals = '[
  {"type": "text", "title": "죄수의 딜레마 쉽게 설명", "body": "각자 자기에게 합리적인 선택을 했는데 결과는 모두에게 더 나빠지는 상황이에요.\n공범 둘을 따로 조사하면, 상대가 어떻게 하든 자백하는 쪽이 형량이 가벼워서 둘 다 자백해요.\n둘 다 버텼다면 더 가벼웠을 텐데, 서로 믿지 못해 더 나쁜 결과에 머물러요."},
  {"type": "table", "title": "죄수의 딜레마 보수표(형량)", "columns": ["A의 선택", "B 자백", "B 부인"], "rows": [["A 자백", "5년, 5년", "0년, 9년"], ["A 부인", "9년, 0년", "1년, 1년"]], "caption": "칸의 앞 숫자는 A, 뒤 숫자는 B의 형량이에요. 자백이 둘 모두의 우월전략이라 둘 다 자백하는 칸이 균형이에요."},
  {"type": "text", "title": "담합이 깨지는 이유", "body": "과점 기업들이 함께 값을 높게 유지하기로 짜도, 혼자 몰래 싸게 팔면 더 큰 이윤을 얻어요.\n그래서 배신이 우월전략이 되어 담합은 안에서부터 깨지기 쉬워요. 담합을 먼저 신고하면 처벌을 줄여 주는 리니언시도 이 구조를 이용해요.\n다만 같은 게임이 계속 반복되면 보복할 수 있어 협조가 유지되기도 해요."},
  {"type": "quiz", "q": "두 회사 모두 광고비를 줄이면 둘 다 이득인데, 상대가 광고를 할까 봐 둘 다 계속 많은 광고비를 써요. 이 상황을 가장 잘 설명하는 것은?", "options": ["죄수의 딜레마", "코즈의 정리", "가격차별", "수확체감의 법칙"], "answer": 0, "explanation": "각자에게는 광고하는 쪽이 늘 나은 선택이라 둘 다 광고해요. 그 결과 둘 다 줄였을 때보다 나빠지니 죄수의 딜레마예요.", "lessonCheck": true},
  {"type": "quiz", "q": "죄수의 딜레마가 보여 주는 것은?", "options": ["개인에게 합리적인 선택이 모두에게 최선은 아닐 수 있어요", "균형은 항상 모두에게 가장 좋은 결과예요", "협조는 언제나 저절로 유지돼요", "상대를 믿지 않으면 항상 이득이에요"], "answer": 0, "explanation": "각자 우월전략을 골랐는데 둘 다 협조했을 때보다 결과가 나빠요. 개인의 합리성과 모두의 이익이 어긋날 수 있다는 뜻이에요."}
]'::jsonb || COALESCE(visuals,'[]'::jsonb)
WHERE id = 521 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "죄수의 딜레마 쉽게 설명"}]'::jsonb;

-- 독점적 경쟁 (787)
UPDATE public.words SET visuals = '[
  {"type": "text", "title": "독점적 경쟁 쉽게 설명", "body": "동네 카페, 미용실처럼 가게는 많지만 맛과 서비스가 조금씩 다른 시장이에요.\n가게가 많고 들어오기 쉬운 점은 완전경쟁을, 상품이 조금씩 달라 값을 어느 정도 정할 수 있는 점은 독점을 닮았어요."},
  {"type": "table", "title": "완전경쟁 vs 독점적 경쟁 vs 과점", "columns": ["구분", "완전경쟁", "독점적 경쟁", "과점"], "rows": [["기업 수", "무수히 많음", "많음", "소수"], ["상품", "동질", "차별화", "동질·차별"], ["진입장벽", "없음", "거의 없음", "높음"], ["장기 초과 이윤", "0", "0", "가능"], ["가격과 한계비용", "P = MC", "P > MC", "P > MC"], ["서로 눈치 보기", "없음", "약함", "강함"]]},
  {"type": "text", "title": "장기에는 이윤 0, 그래도 덜 효율적", "body": "잘되는 가게 근처에 비슷한 가게가 생겨 손님이 나뉘면서 장기에는 초과 이윤이 0이 돼요.\n하지만 가격이 한계비용보다 높아(P > MC) 완전경쟁보다 적게 만들고, 평균비용이 가장 낮은 양까지 만들지 않아 설비에 여유가 남아요."},
  {"type": "quiz", "q": "동네에 새로 연 빵집이 큰 이윤을 내자 근처에 비슷한 빵집이 여럿 생겼어요. 독점적 경쟁시장에서 이 빵집의 초과 이윤은 장기에 어떻게 될까요?", "options": ["0에 가까워져요", "계속 커져요", "독점처럼 그대로 유지돼요", "항상 큰 손실이 나요"], "answer": 0, "explanation": "진입이 자유로워 초과 이윤이 있으면 새 가게가 계속 들어와요. 손님이 나뉘면서 결국 초과 이윤이 0이 될 때까지 진입이 이어져요.", "lessonCheck": true},
  {"type": "quiz", "q": "독점적 경쟁시장의 특징이 아닌 것은?", "options": ["기업들이 서로의 반응을 강하게 의식해요", "상품이 조금씩 차별화돼 있어요", "진입과 퇴출이 비교적 자유로워요", "광고·서비스 같은 비가격 경쟁을 해요"], "answer": 0, "explanation": "서로 눈치를 강하게 보는 상호 의존성은 소수 기업이 있는 과점의 특징이에요."}
]'::jsonb || COALESCE(visuals,'[]'::jsonb)
WHERE id = 787 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "독점적 경쟁 쉽게 설명"}]'::jsonb;

-- 경제적 지대 (832)
UPDATE public.words SET visuals = '[
  {"type": "text", "title": "경제적 지대 쉽게 설명", "body": "생산요소가 받은 돈 가운데, 그 일을 계속하게 하는 데 필요한 최소 금액(이전수입, 즉 기회비용)을 넘는 부분이에요.\n월급 200만 원을 받는 사람이 180만 원만 줘도 회사에 남았을 거라면 20만 원이 경제적 지대예요."},
  {"type": "table", "title": "공급의 탄력성과 경제적 지대", "columns": ["공급곡선", "이전수입", "경제적 지대"], "rows": [["완전 탄력적(수평)", "총수입 전부", "0"], ["우상향", "일부", "일부"], ["완전 비탄력적(수직)", "0", "총수입 전부"]], "caption": "대체할 사람이 드문 스타 선수처럼 공급이 비탄력적일수록 받는 돈 대부분이 경제적 지대예요."},
  {"type": "text", "title": "지대 추구", "body": "경제적 지대를 얻거나 지키려고 새 경쟁자를 막는 규제나 로비에 힘을 쓰는 걸 지대 추구라고 해요.\n로비에 드는 돈과 시간은 새로 만들어 내는 것이 없어서 사회 전체로는 낭비가 돼요."},
