-- 외부효과 (406)
UPDATE public.words SET visuals = '[
  {"type": "text", "title": "외부효과 쉽게 설명", "body": "어떤 행동이 제3자에게 의도치 않은 이득이나 손해를 주는데 그 대가가 오가지 않는 현상이에요.\n공장 매연처럼 손해를 주면 부정적 외부효과(외부불경제), 예방접종처럼 이득을 주면 긍정적 외부효과(외부경제)예요."},
  {"type": "table", "title": "외부효과 4가지", "columns": ["구분", "부정적(외부불경제)", "긍정적(외부경제)"], "rows": [["생산", "공장 매연, 소음", "과수원 옆 양봉"], ["소비", "흡연, 층간소음", "예방접종, 교육"], ["시장에 맡기면", "너무 많이 생산·소비", "너무 적게 생산·소비"]], "caption": "좋은 외부효과도 알맞은 양보다 적게 만들어지니 시장 실패예요."},
  {"type": "text", "title": "외부효과를 바로잡는 방법", "body": "부정적 외부효과에는 피해만큼 세금(피구세)을, 긍정적 외부효과에는 이득만큼 보조금을 줘서 가격 안에 넣어요. 이를 외부효과의 내부화라고 해요.\n배출량을 직접 제한하거나, 총량을 정하고 배출권을 사고팔게 하는 방법도 있어요."},
  {"type": "quiz", "q": "양봉업자가 벌통을 놓으면 옆 과수원 수확이 늘지만, 양봉업자는 꿀 수입만 보고 벌통 수를 정해요. 시장에 맡기면 벌통 수는?", "options": ["사회적으로 알맞은 양보다 적어요", "사회적으로 알맞은 양보다 많아요", "정확히 알맞은 양이에요", "0이 돼요"], "answer": 0, "explanation": "과수원이 얻는 이득이 양봉업자의 계산에 안 들어가는 긍정적 외부효과예요. 그래서 사회적으로 알맞은 양보다 적게 놓아요.", "lessonCheck": true},
  {"type": "quiz", "q": "공장 매연 같은 부정적 외부효과를 줄이는 정부 정책으로 알맞은 것은?", "options": ["피해 크기만큼 세금을 매겨요", "생산에 보조금을 줘요", "제품 가격에 상한을 정해요", "공장의 배출 제한을 없애요"], "answer": 0, "explanation": "피해만큼 세금(피구세)을 매기면 공장이 그 비용까지 계산해 생산을 줄여요. 외부효과를 가격 안에 넣는 내부화예요."}
