UPDATE public.words SET visuals = '[
  {"type": "text", "title": "공공재 쉽게 설명", "body": "국방, 가로등처럼 여럿이 같이 써도 줄지 않고(비경합성), 돈을 안 낸 사람도 못 쓰게 막을 수 없는(비배제성) 재화예요.\n돈을 안 내도 쓸 수 있으니 다들 남이 내주길 기다리는 무임승차가 생기고, 시장에 맡기면 너무 적게 공급돼요."},
  {"type": "table", "title": "재화 4가지 분류", "columns": ["구분", "경합성 있음", "경합성 없음"], "rows": [["배제성 있음", "사적재(빵, 옷)", "클럽재(유료 케이블 TV, OTT)"], ["배제성 없음", "공유자원(공동 어장)", "공공재(국방, 가로등)"]], "caption": "공공재인지는 누가 만드느냐가 아니라 경합성과 배제성으로 정해요."},
  {"type": "text", "title": "공공재의 알맞은 양", "body": "모두가 같은 양을 함께 쓰므로 사람들의 한계편익을 세로로 더해요.\n이 합이 한계비용과 같아지는 양이 사회적으로 알맞아요. 그래서 각자 혼자서는 안 사도 합치면 만들 가치가 있을 수 있어요."},
  {"type": "quiz", "q": "가로등을 세우는 데 60만 원이 들고, 주민 세 명이 얻는 편익은 각각 5만, 30만, 50만 원이에요. 옳은 것은?", "options": ["편익 합이 비용보다 커서 세우는 게 사회적으로 이득이에요", "한 명의 편익도 60만 원이 안 되니 세우면 손해예요", "가장 큰 편익 50만 원만 비용과 비교하면 돼요", "공공재라서 비용을 따질 필요가 없어요"], "answer": 0, "explanation": "공공재는 모두가 함께 쓰므로 편익을 더해 비교해요. 합계 85만 원이 비용 60만 원보다 커요. 하지만 각자 편익을 숨기면 무임승차로 아무도 돈을 안 낼 수 있어요.", "lessonCheck": true},
  {"type": "quiz", "q": "공공재에서 무임승차가 생기는 직접적인 이유는?", "options": ["비배제성(돈을 안 내도 막을 수 없음)", "비경합성(같이 써도 줄지 않음)", "경합성(쓰면 줄어듦)", "배제성(돈을 안 내면 막을 수 있음)"], "answer": 0, "explanation": "돈을 안 낸 사람을 막을 수 없으니 남이 내주길 기다리게 돼요. 무임승차는 비배제성 때문이에요."}
