-- 공유지의 비극 (799)
UPDATE public.words SET visuals = '[
  {"type": "text", "title": "공유지의 비극 쉽게 설명", "body": "공동 목초지나 공동 어장처럼 누구나 쓸 수 있는데(비배제성) 쓰면 줄어드는(경합성) 자원은 먼저 쓰는 사람이 임자예요.\n그래서 각자 서둘러 많이 쓰고, 결국 자원이 바닥나요. 이를 공유지의 비극이라고 해요."},
  {"type": "table", "title": "공공재 vs 공유자원", "columns": ["구분", "공공재", "공유자원"], "rows": [["경합성", "없음", "있음"], ["배제성", "없음", "없음"], ["문제", "무임승차로 과소 공급", "남용으로 고갈"], ["해결", "정부 공급", "재산권 설정, 이용량 제한"]]},
  {"type": "quiz", "q": "누구나 무료로 고기를 잡을 수 있는 바다에서 어부들이 서로 더 많이 잡으려다 물고기가 크게 줄었어요. 이를 막는 방법으로 알맞은 것은?", "options": ["잡을 수 있는 양을 정해 주는 쿼터제", "어선 연료에 보조금 지급", "물고기 가격에 상한 설정", "고기잡이 허가를 더 늘림"], "answer": 0, "explanation": "공유자원은 이용을 막을 수 없어 남용돼요. 잡을 수 있는 양을 정하거나 재산권을 정해 주면 고갈을 막을 수 있어요.", "lessonCheck": true},
  {"type": "quiz", "q": "공유지의 비극이 생기는 자원의 성격은?", "options": ["경합성은 있고 배제성은 없어요", "경합성도 배제성도 없어요", "경합성은 없고 배제성은 있어요", "경합성도 배제성도 있어요"], "answer": 0, "explanation": "쓰면 줄어드는데(경합성) 아무도 막을 수 없으니(비배제성) 서로 먼저 많이 쓰려 해요."}
]'::jsonb || COALESCE(visuals,'[]'::jsonb)
WHERE id = 799 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "공유지의 비극 쉽게 설명"}]'::jsonb;

-- 역선택 (792)
UPDATE public.words SET visuals = '[
  {"type": "text", "title": "역선택 쉽게 설명", "body": "계약 전에 한쪽만 아는 숨겨진 특성 때문에, 정보가 없는 쪽이 결국 나쁜 상대를 고르게 되는 현상이에요.\n중고차를 사는 사람은 차 상태를 모르니 평균값만 내려 하고, 그러면 좋은 차 주인은 팔지 않고 떠나 나쁜 차(레몬)만 남아요."},
  {"type": "flow", "title": "중고차 시장의 역선택", "steps": ["좋은 차 1,000만 원, 나쁜 차 500만 원이 반반 섞여 있어요", "사는 사람은 구분을 못 해 평균 750만 원만 내려 해요", "좋은 차 주인은 1,000만 원 아래로는 안 팔고 떠나요", "나쁜 차만 남고 가격도 500만 원으로 내려가요"]},
  {"type": "text", "title": "역선택 줄이기", "body": "정보를 가진 쪽이 자격증, 보증서, 무사고 이력을 보여 주는 걸 신호 발송이라고 해요.\n정보가 없는 쪽이 건강검진, 신용 조회로 상대를 가려내는 건 선별이에요. 건강보험처럼 모두 가입하게 하면 건강한 사람이 빠져나가는 역선택을 막을 수 있어요."},
  {"type": "quiz", "q": "보험사가 누가 위험한지 몰라 평균 보험료를 받았더니, 건강한 사람은 비싸다며 가입하지 않고 위험한 사람만 몰렸어요. 이 현상은?", "options": ["역선택", "도덕적 해이", "무임승차", "공유지의 비극"], "answer": 0, "explanation": "계약 전에 숨겨진 특성(건강 상태) 때문에 나쁜 상대만 남았으니 역선택이에요.", "lessonCheck": true},
  {"type": "quiz", "q": "역선택을 줄이려고 정보를 가진 쪽이 하는 행동은?", "options": ["중고차 판매자가 성능 보증서를 보여 줘요", "보험사가 가입 전 건강검진을 요구해요", "은행이 대출 전 신용을 조회해요", "보험사가 자기부담금을 둬요"], "answer": 0, "explanation": "정보를 가진 쪽이 알리는 신호 발송이에요. 건강검진과 신용 조회는 정보가 없는 쪽의 선별이고, 자기부담금은 도덕적 해이 대책이에요."}
]'::jsonb || COALESCE(visuals,'[]'::jsonb)
WHERE id = 792 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "역선택 쉽게 설명"}]'::jsonb;

-- 도덕적 해이 (181)
UPDATE public.words SET visuals = '[
  {"type": "text", "title": "도덕적 해이 쉽게 설명", "body": "계약을 맺은 뒤, 상대가 내 행동을 지켜보기 어렵다는 걸 알고 행동이 달라지는 현상이에요.\n보험에 든 뒤 덜 조심하거나, 채용된 뒤 일을 덜 열심히 하는 경우예요. 이름과 달리 꼭 나쁜 마음만 뜻하지는 않아요."},
  {"type": "table", "title": "역선택 vs 도덕적 해이", "columns": ["구분", "역선택", "도덕적 해이"], "rows": [["시점", "계약 전", "계약 후"], ["숨겨진 것", "특성(상품의 질, 건강)", "행동(노력, 조심성)"], ["예", "병을 숨기고 보험 가입", "보험 가입 후 험한 운전"], ["대책", "신호 발송, 선별, 강제 가입", "자기부담금, 감시, 성과급"]]},
  {"type": "text", "title": "도덕적 해이 줄이기", "body": "손해의 일부를 본인이 지게 하면 덜 해이해져요. 보험의 자기부담금이 대표적이에요.\n은행은 담보와 감시를, 회사는 성과급이나 시장보다 높은 효율성 임금을 써요. 주주와 경영자 사이의 주인-대리인 문제도 도덕적 해이의 한 형태라, 경영자에게 주식을 줘 이해관계를 맞추기도 해요."},
  {"type": "quiz", "q": "화재보험에 가입한 뒤 집주인이 소화기를 치우고 전기 점검도 하지 않게 됐어요. 이 현상과 대책을 바르게 짝지은 것은?", "options": ["도덕적 해이 - 자기부담금 도입", "역선택 - 가입 전 건강검진", "도덕적 해이 - 보험 강제 가입", "역선택 - 자격증 제출"], "answer": 0, "explanation": "계약 후 행동이 바뀌었으니 도덕적 해이예요. 손해 일부를 본인이 지게 하는 자기부담금이 대표적인 대책이에요.", "lessonCheck": true},
  {"type": "quiz", "q": "도덕적 해이에 해당하는 것은?", "options": ["대출을 받은 뒤 말한 곳보다 위험한 곳에 돈을 써요", "병을 숨기고 보험에 가입해요", "품질이 나쁜 중고차만 시장에 남아요", "입사 지원자가 자격증을 제출해요"], "answer": 0, "explanation": "계약 후 숨겨진 행동이 바뀐 경우가 도덕적 해이예요. 나머지는 계약 전 숨겨진 특성과 관련된 역선택이나 그 대책이에요."}
]'::jsonb || COALESCE(visuals,'[]'::jsonb)
WHERE id = 181 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "도덕적 해이 쉽게 설명"}]'::jsonb;

NOTIFY pgrst, 'reload schema';

